import type { Answers, AnswerValue, Question } from "./types";
import { isChoiceQuestion, questionTitle } from "./question-kinds";
import {
  multipleChoiceAnswerSchema,
  singleChoiceAnswerSchema,
  sortQuestions,
} from "./types";

export interface CsvResponse {
  startedAt: Date;
  completedAt: Date | null;
  answers: Answers;
}

export const DELETED_OPTION_LABEL = "Opción eliminada";

export function hasOption(question: Question, optionId: string): boolean {
  if (!isChoiceQuestion(question)) return false;
  return question.config.options.some((option) => option.id === optionId);
}

function optionLabel(question: Question, optionId: string) {
  if (!isChoiceQuestion(question)) return optionId;
  return (
    question.config.options.find((option) => option.id === optionId)?.label ??
    DELETED_OPTION_LABEL
  );
}

export function formatAnswer(
  question: Question,
  value: AnswerValue | null | undefined,
): string {
  if (value === null || value === undefined) return "";

  const single = singleChoiceAnswerSchema.safeParse(value);
  if (single.success) {
    return "optionId" in single.data
      ? optionLabel(question, single.data.optionId)
      : `Otro: ${single.data.other}`;
  }
  const multiple = multipleChoiceAnswerSchema.safeParse(value);
  if (multiple.success) {
    const parts: string[] = [];
    let collapsed = false;
    for (const optionId of multiple.data.optionIds) {
      if (hasOption(question, optionId)) {
        parts.push(optionLabel(question, optionId));
      } else if (!collapsed) {
        parts.push(DELETED_OPTION_LABEL);
        collapsed = true;
      }
    }
    if (multiple.data.other) parts.push(`Otro: ${multiple.data.other}`);
    return parts.join("; ");
  }
  if (typeof value === "boolean") return value ? "Sí" : "No";
  return typeof value === "object" ? "" : String(value);
}
